package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;

/** One foreground-only official site. No account-cookie import into the downloader. */
@androidx.media3.common.util.UnstableApi
public class PlatformBrowserActivity extends Activity {
 private String platform="tiktok",lastUrl="";private boolean visible;private WebView web;private LinearLayout holder;private TextView title,status;private Button download,share;private AlertDialog shareDialog,linkDialog;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);platform=PlatformLinks.IDS[PlatformLinks.index(saved==null?getIntent().getStringExtra("platform"):saved.getString("platform"))];String selected=saved==null?getIntent().getStringExtra("url"):saved.getString("url");lastUrl=PlatformLinks.allowed(platform,selected)?selected:PlatformLinks.home(platform);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,12),Ui.dp(this,8)+i.getSystemWindowInsetTop(),Ui.dp(this,12),Ui.dp(this,8)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));title=Ui.text(this,"",21,Ui.TEXT);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));heading.addView(Ui.menuButton(this,"Menu da plataforma",v->Ui.menu(this,v,new String[]{"Escolher plataforma","Abrir link","Recarregar","Início","Abrir no navegador"},new String[]{"Escolher plataforma","Abrir link da plataforma","Recarregar página da plataforma","Início da plataforma","Abrir plataforma no navegador"},new Runnable[]{this::choosePlatform,this::enterLink,()->{if(web!=null)web.reload();},()->load(PlatformLinks.home(platform)),this::external})),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));root.addView(heading);DownloadTabs.add(this,root,2);status=Ui.text(this,"Abra um vídeo público para baixar ou compartilhar. Conteúdos privados ou com verificação podem não ficar disponíveis.",12,Ui.MUTED);root.addView(status);holder=new LinearLayout(this);holder.setOrientation(LinearLayout.VERTICAL);root.addView(holder,new LinearLayout.LayoutParams(-1,0,1));LinearLayout actions=new LinearLayout(this);download=Ui.button(this,"Baixar",v->analyze());download.setContentDescription("Baixar vídeo da plataforma");share=Ui.button(this,"Compartilhar",v->share());share.setContentDescription("Compartilhar vídeo da plataforma");actions.addView(download,new LinearLayout.LayoutParams(0,-2,1));actions.addView(share,new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);update();}
 private void update(){if(title!=null)title.setText(PlatformLinks.NAMES[PlatformLinks.index(platform)]+" no Onda");String post=PlatformLinks.post(platform,lastUrl);if(download!=null)download.setEnabled(!post.isEmpty());if(share!=null)share.setEnabled(!post.isEmpty());}
 @android.annotation.SuppressLint("SetJavaScriptEnabled") private void createBrowser(){try{WebView next=new WebView(this);web=next;WebSettings settings=next.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setSupportMultipleWindows(false);settings.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptThirdPartyCookies(next,false);next.setContentDescription("Página oficial da plataforma");next.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(!request.isForMainFrame())return false;if(PlatformLinks.allowed(platform,request.getUrl().toString()))return false;status.setText("Este endereço abre fora da plataforma. Use Abrir no navegador se desejar continuar.");return true;}@Override public void doUpdateVisitedHistory(WebView view,String url,boolean reload){remember(view,url);}@Override public void onPageFinished(WebView view,String url){remember(view,url);}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())status.setText("Não foi possível abrir a página. Confira a conexão ou use Abrir link.");}});next.setDownloadListener((url,a,d,m,n)->status.setText("Abra o post e use Baixar para consultar os formatos disponíveis."));holder.addView(next,new LinearLayout.LayoutParams(-1,-1));next.resumeTimers();next.loadUrl(lastUrl);}catch(RuntimeException error){closeBrowser();status.setText("Atualize o Android System WebView ou abra a plataforma no navegador.");}}
 private void remember(WebView view,String url){if(!visible||view!=web||!PlatformLinks.allowed(platform,url)||!java.util.Objects.equals(url,view.getUrl()))return;lastUrl=url;update();status.setText(PlatformLinks.post(platform,lastUrl).isEmpty()?"Abra um vídeo ou use Menu → Abrir link para selecionar o post.":"Vídeo selecionado • baixe ou escolha compartilhar o arquivo ou o link.");}
 private void load(String url){if(!PlatformLinks.allowed(platform,url))return;lastUrl=url;update();if(web!=null)web.loadUrl(url);}
 private void closeBrowser(){WebView old=web;web=null;if(old!=null){holder.removeView(old);old.stopLoading();old.onPause();old.pauseTimers();old.destroy();}}
 private void analyze(){String post=PlatformLinks.post(platform,lastUrl);if(!post.isEmpty())startActivity(new Intent(this,DownloadsActivity.class).putExtra("analyze_media_link",post).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
 private void share(){String post=PlatformLinks.post(platform,lastUrl);if(post.isEmpty())return;if(shareDialog!=null)shareDialog.dismiss();shareDialog=VideoShareFlow.show(this,post);}
 private void choosePlatform(){new AlertDialog.Builder(this).setTitle("Escolher plataforma").setSingleChoiceItems(PlatformLinks.NAMES,PlatformLinks.index(platform),(d,n)->{platform=PlatformLinks.IDS[n];lastUrl=PlatformLinks.home(platform);closeBrowser();update();if(visible)createBrowser();d.dismiss();}).setNegativeButton("Cancelar",null).show();}
 private void enterLink(){EditText input=new EditText(this);Ui.input(input);input.setHint("Link de vídeo da plataforma");input.setContentDescription("Link para abrir na plataforma");linkDialog=new AlertDialog.Builder(this).setTitle("Abrir link").setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Abrir",null).create();linkDialog.setOnShowListener(d->linkDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String raw=input.getText().toString().trim();if(!PlatformLinks.allowed(platform,raw)){input.setError("Use um endereço HTTPS desta plataforma");return;}linkDialog.dismiss();load(raw);}));linkDialog.show();}
 private void external(){try{startActivity(Intent.createChooser(new Intent(Intent.ACTION_VIEW,Uri.parse(lastUrl)),"Abrir plataforma"));}catch(Exception e){status.setText("Nenhum navegador disponível.");}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.hasExtra("platform")){platform=PlatformLinks.IDS[PlatformLinks.index(intent.getStringExtra("platform"))];String selected=intent.getStringExtra("url");lastUrl=PlatformLinks.allowed(platform,selected)?selected:PlatformLinks.home(platform);closeBrowser();update();if(visible)createBrowser();}}
 @Override protected void onResume(){super.onResume();visible=true;if(web==null)createBrowser();else{web.onResume();web.resumeTimers();}}
 @Override protected void onPause(){visible=false;if(web!=null){web.evaluateJavascript("document.querySelectorAll('video,audio').forEach(function(m){m.pause();});",null);web.onPause();web.pauseTimers();}super.onPause();}
 @Override protected void onStop(){closeBrowser();super.onStop();}
 @Override protected void onDestroy(){closeBrowser();if(shareDialog!=null)shareDialog.dismiss();if(linkDialog!=null)linkDialog.dismiss();super.onDestroy();}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle saved){saved.putString("platform",platform);saved.putString("url",lastUrl);super.onSaveInstanceState(saved);}
}
